llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Morphine, a morphinan with a free 3-phenol, has an oral bioavailability of 40% in humans, showing that the morphinan scaffold can achieve F≥20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Ethylmorphine, with a 3-ethoxy group, has a median oral bioavailability of 74%, indicating that 3-O-substitution markedly increases F relative to free-phenol analogues.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Morphine slow-release tablets in elderly subjects have F=28.7±3.6%, still above the 20% threshold, so even the lower-F morphinan evidence does not affirm F<20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C40"],
      "claim": "Morphine immediate-release has an estimated bioavailability of 20–25% in volunteers, near the threshold, highlighting that free-phenol morphinans have limited oral bioavailability and that additional metabolic liabilities could push F below 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The supplied morphinan evidence consistently shows F≥20%, but the query is naloxone, whose 6-keto and N-allyl groups are known to cause extensive first-pass metabolism (glucuronidation and ketone reduction), resulting in oral bioavailability well below 20%. The high-F analogues lack these liabilities, so their evidence is outweighed.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for naloxone in the supplied evidence.",
    "No analogue with both 6-keto and N-allyl substituents is present to directly model the query's metabolic liability.",
    "Lack of data on the query's specific first-pass metabolism and transporter involvement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

